on_save_model_field:
if (!empty([[[field]]]) && is_array([[[field]]]))
{
	$tagSub = [];
	$companyGuid = $data['guid'] ?? 'error';

	// Retrieve existing tag records for this company
	$existing = Super___9d76b8dc_3883_4755_b11c_131d19ca8a53___Power::_('Data.Items')
		->table('company_tag')
		->get([$companyGuid], 'company');

	// Index existing records by tag for quick lookup
	$existingMap = [];
	if (!empty($existing))
	{
		foreach ($existing as $row)
		{
			if (!empty($row->tag))
			{
				$existingMap[$row->tag] = $row->guid ?? '';
			}
		}
	}

	// get max allowed number of items
	$max = Super___640b5352_fb09_425f_a26e_cd44eda03f15___Power::getParams()->get('max_tags', 5);
	$m = 0;

	// Build subform data entries
	foreach ([[[field]]] as $n => $tag)
	{
		if (!is_string($tag) || $tag === '')
		{
			continue; // Skip invalid entries
		}

		if ($m >= $max)
		{
			break;
		}

		$tagSub["tag{$n}"] = [
			'guid'     => $existingMap[$tag] ?? '',
			'tag' => $tag
		];

		$m++;
	}

	Super___9d76b8dc_3883_4755_b11c_131d19ca8a53___Power::_('Data.Subform')
		->table('company_tag')
		->set($tagSub, 'guid', 'company', $companyGuid);
		unset($data['tags']);
}
